import DialogAction from 'd2/sdk/controls/dialogs/generic/dialog.action';

class ActionBackDialog extends DialogAction {
  execute(options = {}) {
    const {dialog, dialogState} = options;

    return dialogState.previousForm()
      .then((formData) => {
        const {formName} = formData;
        dialog.gotoStep(formName);
      });
  }
}

Object.defineProperty(ActionBackDialog.prototype.constructor, 'name', {value: 'ActionBackDialog'});

export default ActionBackDialog;