import {Collection} from 'nuc/lib/backbone';
import FormModel from 'd2/sdk/controls/form/form.model';
import DialogFormCollectionView from 'd2/dialogs/generic/dialog.form.collection.view';
import DialogContentView from 'd2/sdk/controls/dialogs/generic/dialog.content.view';

class FormCollection extends Collection {
  constructor(models, options) {
    super(models, options);
    this.fetched = true;
  }
}

Object.assign(FormCollection.prototype, {
  model: FormModel
});

class DefaultDialogContentView extends DialogContentView {
  constructor(options={}) {
    super(options);
  }

  resolveView(options = {}) {
    return new Promise((res) => {

      // DTWO-105380 fix
      // Incase of readonly mode, though we get form_mode as 'read' from dialog xml, we are setting as 'update'.
      // By passing 'read', due to CSUI form field behavior, on clicking a text field, the value gets hidden from form
      // In D2SV metadata properties page, we are using form_mode as 'update' while displaying the values.
      // Hence using 'update' if form_mode value is coming as 'read'
      let formMode = options['originalResponse'] &&
      options['originalResponse']['page-content'] &&
      options['originalResponse']['page-content']['dialog'] &&
      options['originalResponse']['page-content']['dialog']['form_mode'] &&
      options['originalResponse']['page-content']['dialog']['form_mode'] === 'read' ? 'update' : 'create';

      let formView = new DialogFormCollectionView({
        formMode: formMode,
        layoutMode: options.layoutMode,
        collection: new FormCollection(options.formSchema.propertiesConfig)
      });

      res(formView);
    });
  }
}

Object.defineProperty(DefaultDialogContentView.prototype.constructor, 'name', {value: 'DefaultDialogContentView'});

export default DefaultDialogContentView;